head.script:
scwin.contnId;
scwin.gLdMktTp = js_market;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.libRoundPanel.PanelToGroupBox(panel_Top);
        // edt_SDate.text = cGetToday("yyyymmdd");
        btn_input.show("");
        vCurDate = $c.ut.cGetToday("yyyymmdd");
        edt_SDate.setValue($c.ut.cGetMinusMonth(vCurDate.substring(0, 4), vCurDate.substring(4, 6), vCurDate.substring(6, 8), 1)); // 한달전 날짜
        edt_EDate.setValue($c.ut.cGetToday("yyyymmdd"));
        rdo_MKT_ID.setValue(scwin.gLdMktTp);
        if (scwin.gLdMktTp === '1' || scwin.gLdMktTp === '2') {
            // showObj(panel_mkt, false);
            panel_mkt.show("");
        }
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDMGT30300.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_tmp_1_OnDblClick
 * @description grd_tmp_1 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_tmp_1_OnDblClick = async function(row, colid) {
    try {
        if (colid === 'TITLE') {
            const options = {
                id: "ULDMGT30301",
                title: "HelpDesk 수정",
                type: "browserPopup",
                width: "655px",
                height: "510px",
                callbackFn: "scwin.popupCallback"
            };

            $c.win.openPopup("/bizspt/ULDMGT30301.gfm", options);
            await scwin.listSync();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDMGT30300.grd_tmp_1_OnDblClick" });
    }
};

/**
 * @method
 * @name cmb_PeriodTp_OnSelChange
 * @description cmb_PeriodTp 선택 변경 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PeriodTp_OnSelChange = function() {
    try {
        const vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
        $c.stf.setFromToDate(vTp, edt_SDate, edt_EDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT30300.cmb_PeriodTp_OnSelChange" });
    }
};

/**
 * @method
 * @name btn_input_onclick
 * @description btn_input 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_input_onclick = async function() {
    try {
        scwin.contnId = "input";
        const options = {
            id: "ULDMGT30301",
            title: "HelpDesk 등록",
            type: "browserPopup",
            width: "655px",
            height: "510px",
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("/bizspt/ULDMGT30301.gfm", options);
        scwin.contnId = "";
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDMGT30300.btn_input_onclick" });
    }
};

/**
 * @method
 * @name dts_listShareRoom_OnLoadCompleted
 * @description dts_listShareRoom 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_listShareRoom_OnLoadCompleted = function(rowcount) {
    try {
        txb_TotCnt.setValue("총 " + rowcount + "건");
        if (rowcount <= 0) {
            dts_listShareRoom.removeAll();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT30300.dts_listShareRoom_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_listShareRoom_OnLoadError
 * @description dts_listShareRoom 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.dts_listShareRoom_OnLoadError = function() {
};

/**
 * @method
 * @name btn_select_onclick
 * @description btn_select 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_select_onclick = async function() {
    try {
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDMGT30300.btn_select_onclick" });
    }
};

/**
 * @method
 * @name icn_SCal_onclick
 * @description icn_SCal 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.icn_SCal_onclick = function() {
    try {
        popUpCalendar2(edt_SDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT30300.icn_SCal_onclick" });
    }
};

/**
 * @method
 * @name icn_ECal_onclick
 * @description icn_ECal 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.icn_ECal_onclick = function() {
    try {
        popUpCalendar2(edt_EDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT30300.icn_ECal_onclick" });
    }
};

/**
 * @method
 * @name img_toExcel_onclick
 * @description img_toExcel 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_toExcel_onclick = function() {
    try {
        $c.stf.doLogSave("ULDMGT30300.xml", SCREN_PROCS_TP_CD_07, '');
        $c.data.downloadGridViewExcel(grd_tmp_1, {fileName: "건의사항 목록", type: "2"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT30300.img_toExcel_onclick" });
    }
};

/**
 * @method
 * @name rdo_MKT_ID_OnSelChange
 * @description rdo_MKT_ID 선택 변경 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.rdo_MKT_ID_OnSelChange = function() {
    // fn_SetCtrlByMktId();

};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    if (await scwin.dateCheck() === false) {
        return;
    }
    const KeyWord = $c.cp.valueOfIndex(keyword, "VALUE", keyword.getSelectedIndex());
    const Condition = condition1.getValue();
    const UserId = condition2.getValue();
    const SDate = edt_SDate.getValue();
    const EDate = edt_EDate.getValue();
    const ProcsStat = $c.cp.valueOfIndex(cmb_Procs_Stat, "VALUE", cmb_Procs_Stat.getSelectedIndex());
    const CreatlocTpCd = $c.cp.valueOfIndex(cmb_Creatloc_Tp_Cd, "VALUE", cmb_Creatloc_Tp_Cd.getSelectedIndex());
    const sbmOptions = {
        id : "sbm_dts_listShareRoom",
        action : "/ShareRoom.do",
        ref : "",
        target : "dts_listShareRoom=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setContnId
 * @description set Contn Id 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setContnId = function(obj) {
    if (scwin.contnId !== "input") {
        scwin.contnId = dts_listShareRoom.getCellData(Number(obj), "CONTN_ID");
    }
};

/**
 * @method
 * @name getContnId
 * @description get Contn Id 처리
 * @returns {void}
 * @hidden N
 */
scwin.getContnId = function() {
    return scwin.contnId;
};

/**
 * @method
 * @name dateCheck
 * @description date Check 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dateCheck = async function() {
    if (parseInt(edt_SDate.getValue(), '10') > parseInt(edt_EDate.getValue(), '10')) {
        await $c.win.alert("[조회기간 시작일은 종료일보다 작아야 합니다.]다시 입력해주세요");
        edt_SDate.setValue($c.ut.cGetToday("yyyymmdd"));
        edt_EDate.setValue($c.ut.cGetToday("yyyymmdd"));
        return false;
    }
};
